
const KEY='mpr_squad_daily_work_details_v1';
let db=JSON.parse(localStorage.getItem(KEY)||'{"duties":[],"bills":[],"people":[],"pay":[],"custom":[]}');
let activePerson=null;
db.settings=db.settings||{};db.bills=(db.bills||[]).map(b=>{const total=(Number(b.goingFare??b.travel)||0)+(Number(b.returnFare)||0)+(Number(b.food)||0)+(Number(b.other)||0);const wasPaid=b.paid===true||b.paid==='true';const amountPaid=b.amountPaid===undefined?(wasPaid?total:0):Math.min(total,Math.max(0,Number(b.amountPaid)||0));return {...b,amountPaid,paid:amountPaid>=total&&total>0};});
db.profile=db.profile||{name:'MP RAKIB sordar',role:'MPR SQUAD',birthday:'12 August',contact:'019090-62744',tagline:'Apk development & Digital platform service',photo:''};db.profile.name=db.profile.name||'MP RAKIB sordar';db.profile.role=db.profile.role||'MPR SQUAD';db.profile.birthday=db.profile.birthday||'12 August';db.profile.contact=db.profile.contact||'019090-62744';db.profile.tagline=db.profile.tagline||'Apk development & Digital platform service';db.profile.photo=db.profile.photo||'data:image/png;base64,';db.security=db.security||{pin:''};db.socials=Array.isArray(db.socials)?db.socials:[];if(db.socials.length===0){db.socials=[{id:'mpr-youtube-qr',platform:'YouTube',label:'MPR SQUAD YouTube',url:'',qr:'data:image/jpeg;base64,'}];}db.admin=db.admin||{pin:''};
const $=id=>document.getElementById(id);
const money=n=>'৳'+(Number(n)||0).toLocaleString('en-BD',{maximumFractionDigits:2});
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
function updateDateTime(){const d=new Date();const clock=$('liveClock'),date=$('liveDate'),weekday=$('liveWeekday');if(clock)clock.textContent=new Intl.DateTimeFormat('bn-BD',{hour:'2-digit',minute:'2-digit',hour12:true}).format(d);if(date)date.textContent=new Intl.DateTimeFormat('bn-BD',{day:'numeric',month:'long',year:'numeric'}).format(d);if(weekday)weekday.textContent=new Intl.DateTimeFormat('bn-BD',{weekday:'long'}).format(d)}
updateDateTime();setInterval(updateDateTime,1000);
function setTheme(name){const allowed=['ocean','sunset','emerald','berry'];const theme=allowed.includes(name)?name:'ocean';db.settings=db.settings||{};db.settings.theme=theme;document.documentElement.dataset.theme=theme;const sel=document.getElementById('themeChoice');if(sel)sel.value=theme;localStorage.setItem(KEY,JSON.stringify(db));}
function applySavedTheme(){setTheme(db.settings?.theme||'ocean')}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));renderHome();renderProfile();return true}catch(err){alert('তথ্য সংরক্ষণ করা যায়নি। ফোনে জায়গা খালি করুন এবং এখনই JSON ব্যাকআপ নিন। আপনার বর্তমান স্ক্রিনের তথ্য হারাবেন না।');return false}}
function formObj(form){return Object.fromEntries(new FormData(form).entries())}
function refreshPersonLinks(){document.querySelectorAll('select.person-link').forEach(sel=>{const keep=sel.value;sel.innerHTML='<option value="">ব্যক্তি নির্বাচন (ঐচ্ছিক)</option>'+(db.people||[]).map(p=>`<option value="${esc(p.code)}">${esc(p.name)} (${esc(p.code)})</option>`).join('');if([...sel.options].some(o=>o.value===keep))sel.value=keep;});refreshReportPeople()}
function personLabel(code){const p=(db.people||[]).find(x=>x.code===code);return p?`${p.name} (${p.code})`:(code||'ব্যক্তি নির্ধারিত নয়')}

function renderProfile(){if(!$('profileNameView'))return;$('profileNameView').textContent=db.profile.name||'আপনার নাম';$('profileRoleView').textContent=(db.profile.role||'MPR SQUAD')+' • '+(db.profile.tagline||'Apk development & Digital platform service');let src=db.profile.photo||'';$('profilePhotoView').src=src||avatarPlaceholder();if($('profilePhotoEdit'))$('profilePhotoEdit').src=src||avatarPlaceholder();let card=$('profilePhotoView').parentElement;if(card){let meta=card.querySelector('.profile-meta');if(!meta){meta=document.createElement('div');meta.className='profile-meta muted';meta.style.cssText='font-size:12px;margin-top:5px';card.querySelector('div[style*="min-width"]')?.appendChild(meta)}meta.textContent='🎂 Birthday: '+(db.profile.birthday||'12 August')+'  |  ☎ Contact: '+(db.profile.contact||'019090-62744')}}
function avatarPlaceholder(){return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="120" height="120"><rect width="100%" height="100%" fill="#dbeafe"/><circle cx="60" cy="43" r="22" fill="#7895b5"/><path d="M18 115c4-29 20-42 42-42s38 13 42 42" fill="#7895b5"/></svg>')}
function renderSecurity(){renderProfile()}
// Profile identity is locked in this build.
function loadProfilePhoto(e){let file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/'))return alert('একটি ছবি নির্বাচন করুন।');let reader=new FileReader();reader.onload=()=>{let img=new Image();img.onload=()=>{let c=document.createElement('canvas'),scale=Math.min(1,600/Math.max(img.width,img.height));c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);db.profile.photo=c.toDataURL('image/jpeg',.78);save();renderProfile();};img.src=reader.result};reader.readAsDataURL(file)}
function removePin(){if(!db.security.pin)return alert('কোনো PIN সেট করা নেই।');if(!confirm('অ্যাপের PIN বন্ধ করবেন?'))return;db.security.pin='';save();alert('PIN বন্ধ করা হয়েছে।')}
function lockApp(){if(!db.security.pin)return alert('আগে প্রোফাইল ও সিকিউরিটি থেকে PIN সেট করুন।');$('unlockPin').value='';$('unlockError').textContent='';$('lockScreen').classList.add('show');$('menu').classList.remove('open')}
function unlockApp(){if($('unlockPin').value===db.security.pin){$('lockScreen').classList.remove('show');$('unlockError').textContent=''}else{$('unlockError').textContent='PIN সঠিক নয়, আবার চেষ্টা করুন।';$('unlockPin').value=''}}

function num(v){return Number(v)||0}
let adminUnlocked=false;
let pendingSocialQr='';
function socialSafeUrl(raw){try{const u=new URL(String(raw||'').trim());return (u.protocol==='https:'||u.protocol==='http:')?u.href:''}catch(e){return ''}}
function socialEscape(v){return esc(String(v??''))}
function renderSocials(){const pub=$('socialPublicList'),adm=$('socialAdminList');if(!pub)return;const rows=db.socials||[];pub.innerHTML=rows.length?rows.map(x=>{const url=socialSafeUrl(x.url);return `<article class="social-item"><h4>${socialEscape(x.platform)}${x.label?' · '+socialEscape(x.label):''}</h4>${url?`<a href="${socialEscape(url)}" target="_blank" rel="noopener noreferrer">${socialEscape(url)}</a>`:'<span class="muted">লিংক নেই</span>'}${x.qr?`<img class="social-qr" src="${x.qr}" alt="${socialEscape(x.platform)} QR কোড">`:''}</article>`}).join(''):'<p class="muted">এখনো কোনো লিংক বা QR কোড যোগ করা হয়নি।</p>';if(adm){adm.innerHTML=rows.length?rows.map(x=>`<article class="social-item"><h4>${socialEscape(x.platform)}${x.label?' · '+socialEscape(x.label):''}</h4><div class="muted" style="overflow-wrap:anywhere">${socialEscape(x.url||'')}</div><div class="admin-tools"><button type="button" onclick="editSocial('${socialEscape(x.id)}')">পরিবর্তন</button><button type="button" class="secondary" onclick="deleteSocial('${socialEscape(x.id)}')">মুছুন</button></div></article>`).join(''):'<p class="muted">কোনো রেকর্ড নেই।</p>'}$('adminStatus').textContent=adminUnlocked?'অ্যাডমিন আনলক':'লক করা';$('socialEditor').classList.toggle('show',adminUnlocked)}
function adminLogin(){if(!db.admin.pin){const p=prompt('নতুন অ্যাডমিন PIN তৈরি করুন (কমপক্ষে ৬ অক্ষর):');if(p===null)return;if(String(p).length<6)return alert('PIN কমপক্ষে ৬ অক্ষরের হতে হবে।');const q=prompt('একই PIN আবার লিখুন:');if(q!==p)return alert('PIN মিলেনি। আবার চেষ্টা করুন।');db.admin.pin=String(p);save();adminUnlocked=true;renderSocials();alert('অ্যাডমিন PIN তৈরি হয়েছে। এটি নিরাপদে মনে রাখুন।');return}const p=prompt('অ্যাডমিন PIN লিখুন:');if(p===null)return;if(String(p)!==String(db.admin.pin))return alert('PIN সঠিক নয়।');adminUnlocked=true;renderSocials()}
function adminLogout(){adminUnlocked=false;renderSocials();resetSocialForm()}
function changeAdminPin(){if(!adminUnlocked){alert('আগে অ্যাডমিন PIN দিয়ে প্রবেশ করুন।');return}const p=prompt('নতুন PIN দিন (কমপক্ষে ৬ অক্ষর):');if(p===null)return;if(String(p).length<6)return alert('PIN কমপক্ষে ৬ অক্ষরের হতে হবে।');const q=prompt('নতুন PIN আবার লিখুন:');if(q!==p)return alert('PIN মিলেনি।');db.admin.pin=String(p);save();alert('অ্যাডমিন PIN পরিবর্তন হয়েছে।')}
function loadSocialQr(e){const file=e.target.files&&e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){alert('শুধু ছবির ফাইল নির্বাচন করুন।');e.target.value='';return}if(file.size>2*1024*1024){alert('QR ছবিটি ২ MB-এর কম রাখুন।');e.target.value='';return}const r=new FileReader();r.onload=()=>{pendingSocialQr=String(r.result||'');$('qrPreview').innerHTML=pendingSocialQr?`<img class="social-qr" src="${pendingSocialQr}" alt="QR preview">`:''};r.readAsDataURL(file)}
function resetSocialForm(){const f=$('socialForm');if(!f)return;f.reset();f.elements.id.value='';pendingSocialQr='';$('qrPreview').innerHTML=''}
function editSocial(id){if(!adminUnlocked)return alert('অ্যাডমিন প্রবেশ প্রয়োজন।');const x=(db.socials||[]).find(z=>z.id===id);if(!x)return;const f=$('socialForm');f.elements.id.value=x.id;f.elements.platform.value=x.platform;f.elements.label.value=x.label||'';f.elements.url.value=x.url||'';pendingSocialQr=x.qr||'';$('qrPreview').innerHTML=pendingSocialQr?`<img class="social-qr" src="${pendingSocialQr}" alt="QR preview">`:'';f.scrollIntoView({behavior:'smooth',block:'center'})}
function deleteSocial(id){if(!adminUnlocked)return alert('অ্যাডমিন প্রবেশ প্রয়োজন।');if(!confirm('এই প্ল্যাটফর্মের লিংক ও QR মুছে ফেলবেন?'))return;db.socials=(db.socials||[]).filter(x=>x.id!==id);save();renderSocials()}
document.addEventListener('DOMContentLoaded',()=>{const f=$('socialForm');if(f)f.addEventListener('submit',e=>{e.preventDefault();if(!adminUnlocked)return alert('অ্যাডমিন প্রবেশ প্রয়োজন।');const d=formObj(f),url=socialSafeUrl(d.url);if(!url)return alert('সঠিক http:// অথবা https:// লিংক দিন।');const old=(db.socials||[]).find(x=>x.id===d.id);const item={id:d.id||('soc_'+Date.now()+'_'+Math.random().toString(36).slice(2,7)),platform:d.platform,label:d.label.trim(),url,qr:pendingSocialQr||(old&&old.qr)||''};db.socials=db.socials||[];const i=db.socials.findIndex(x=>x.id===item.id);if(i>=0)db.socials[i]=item;else db.socials.push(item);if(save()){resetSocialForm();renderSocials();alert('সোশ্যাল লিংক সংরক্ষণ হয়েছে।')}})});

let screenStack=['homeScreen'];
function showScreen(id,fromBack=false){if(!$(id))return;const current=document.querySelector('.screen.active')?.id||'homeScreen';if(!fromBack&&current!==id){screenStack.push(id);}document.querySelectorAll('.screen').forEach(s=>s.classList.remove('active'));$(id).classList.add('active');$('menu').classList.remove('open');if(id==='expenseScreen')renderFolders();if(id==='dutyScreen')renderDuty();if(id==='billScreen')renderBills();if(id==='payScreen')renderPay();if(id==='customScreen')renderCustom();if(id==='developerScreen')renderSocials();if(id==='personSummaryScreen')renderPersonSummary();if(id==='locationScreen')renderLocationSummary();if(id==='summaryScreen')renderSummary();renderHome()}
function goHome(){screenStack=['homeScreen'];showScreen('homeScreen',true)}
function appBack(){const active=document.querySelector('.screen.active')?.id||'homeScreen';if(active==='personScreen'){showScreen('expenseScreen');return true;}if(screenStack.length>1){screenStack.pop();const prev=screenStack.pop()||'homeScreen';showScreen(prev,true);return true;}if(active!=='homeScreen'){goHome();return true;}return false}
window.appBackFromAndroid=function(){return appBack()};
function aggregateEntries(month){const rows=[];(db.bills||[]).filter(x=>!month||inMonth(x.date,month)).forEach(x=>rows.push({date:x.date,place:x.place||'স্থান উল্লেখ নেই',person:personLabel(x.personCode),amount:billAmount(x),kind:'বিল'}));(db.people||[]).forEach(p=>(p.records||[]).filter(x=>!month||inMonth(x.date,month)).forEach(x=>rows.push({date:x.date,place:x.place||'স্থান উল্লেখ নেই',person:p.name+' ('+p.code+')',amount:num(x.goingFare??x.travel)+num(x.returnFare)+num(x.food)+num(x.other),kind:'ব্যক্তিগত খরচ'})));return rows}
function renderPersonSummary(){const el=$('personSummaryRows');if(!el)return;const people=db.people||[];el.innerHTML='<table><thead><tr><th>ব্যক্তি</th><th>রেকর্ড</th><th>মোট খরচ</th><th>বিস্তারিত</th></tr></thead><tbody>'+people.map((p,i)=>{const total=(p.records||[]).reduce((a,x)=>a+num(x.goingFare??x.travel)+num(x.returnFare)+num(x.food)+num(x.other),0);return `<tr><td>${esc(p.name)} (${esc(p.code)})</td><td>${(p.records||[]).length}</td><td>${money(total)}</td><td><button onclick="openPerson(${i})">খুলুন</button></td></tr>`}).join('')+'</tbody></table>'+(people.length?'':'<p>এখনো কোনো ব্যক্তি যোগ করা হয়নি।</p>')}
function renderLocationSummary(){const el=$('locationSummaryRows');if(!el)return;const groups={};aggregateEntries('').forEach(x=>{const k=x.place.trim()||'স্থান উল্লেখ নেই';groups[k]=(groups[k]||0)+x.amount});el.innerHTML='<table><thead><tr><th>স্থান</th><th>মোট খরচ</th></tr></thead><tbody>'+Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${money(v)}</td></tr>`).join('')+'</tbody></table>'+(Object.keys(groups).length?'':'<p>এখনো কোনো স্থানভিত্তিক রেকর্ড নেই। বিল বা ব্যক্তিগত খরচে স্থানের নাম লিখুন।</p>')}
function renderSummary(){const m=$('summaryMonth');if(!m)return;if(!m.value)m.value=today().slice(0,7);const rows=aggregateEntries(m.value),bill=rows.filter(x=>x.kind==='বিল').reduce((a,x)=>a+x.amount,0),person=rows.filter(x=>x.kind==='ব্যক্তিগত খরচ').reduce((a,x)=>a+x.amount,0);$('summaryStats').innerHTML=stat('মোট রেকর্ড',rows.length)+stat('বিলের মোট',money(bill))+stat('ব্যক্তিগত খরচ',money(person))+stat('সর্বমোট',money(bill+person));$('summaryRows').innerHTML='<table><thead><tr><th>বিভাগ</th><th>তারিখ</th><th>ব্যক্তি</th><th>স্থান</th><th>পরিমাণ</th></tr></thead><tbody>'+rows.map(x=>`<tr><td>${x.kind}</td><td>${esc(x.date||'')}</td><td>${esc(x.person)}</td><td>${esc(x.place)}</td><td>${money(x.amount)}</td></tr>`).join('')+'</tbody></table>'+(rows.length?'':'<p>এই মাসে কোনো হিসাব নেই।</p>')}
function toggleMenu(){$('menu').classList.toggle('open')}
function monthVal(id){return $(id).value||today().slice(0,7)}
function inMonth(date,m){return (date||'').slice(0,7)===m}
function hours(a,b){if(!a||!b)return 0;let [h1,m1]=a.split(':').map(Number),[h2,m2]=b.split(':').map(Number);let x=h2*60+m2-h1*60-m1;if(x<0)x+=1440;return x/60}
function stat(label,value){return `<div class="stat"><small>${label}</small><b>${value}</b></div>`}
function renderHome(){let m=today().slice(0,7),ds=db.duties.filter(x=>inMonth(x.date,m)),bs=db.bills.filter(x=>inMonth(x.date,m));let ex=db.people.flatMap(p=>p.records).filter(x=>inMonth(x.date,m)).reduce((s,x)=>s+num(x.goingFare??x.travel)+num(x.returnFare)+num(x.food)+num(x.other),0);$('homeStats').innerHTML=stat('ডিউটি দিন',ds.filter(x=>x.status==='ডিউটি').length)+stat('ডে অফ',ds.filter(x=>x.status==='ডে অফ').length)+stat('মোট বিল',money(bs.reduce((s,x)=>s+billAmount(x),0)))+stat('পরিশোধিত',money(bs.reduce((s,x)=>s+paidAmount(x),0)))+stat('বাকি বিল',money(bs.reduce((s,x)=>s+dueAmount(x),0)))+stat('ব্যক্তিগত খরচ',money(ex))}
$('dutyForm').addEventListener('submit',e=>{e.preventDefault();db.duties.push(formObj(e.target));save();e.target.reset();renderDuty()});
function renderDuty(){let m=$('dutyMonth').value||today().slice(0,7);$('dutyMonth').value=m;let a=db.duties.filter(x=>inMonth(x.date,m));let work=a.filter(x=>x.status==='ডিউটি'),off=a.filter(x=>x.status==='ডে অফ'),hrs=work.reduce((s,x)=>s+hours(x.start,x.end),0);$('dutyStats').innerHTML=stat('মোট ডিউটি দিন',work.length)+stat('মোট ডে অফ',off.length)+stat('মোট ডিউটি সময়',hrs.toFixed(2)+' ঘণ্টা');$('dutyRows').innerHTML=a.map((x,i)=>`<tr><td>${x.date}</td><td>${x.status}</td><td>${x.start||'—'}</td><td>${x.end||'—'}</td><td>${x.status==='ডিউটি'?hours(x.start,x.end).toFixed(2)+' ঘণ্টা':'—'}</td><td>${esc(x.place)}</td><td>${esc(personLabel(x.personCode))}</td><td><button class="danger" onclick="del('duties',${db.duties.indexOf(x)},renderDuty)">মুছুন</button></td></tr>`).join('')}
$('billForm').addEventListener('submit',e=>{e.preventDefault();const x=formObj(e.target);const total=billAmount(x);x.paid=x.paid==='true';x.amountPaid=x.paid?total:0;x.paymentDate=x.paid?today():'';db.bills.push(x);save();e.target.reset();renderBills()});
function billAmount(x){return num(x.goingFare??x.travel)+num(x.returnFare)+num(x.food)+num(x.other)}
function paidAmount(x){const total=billAmount(x);return Math.min(total,Math.max(0,Number(x.amountPaid??(x.paid?total:0))||0))}
function dueAmount(x){return Math.max(0,billAmount(x)-paidAmount(x))}
function addBillPayment(i){const b=db.bills[i];if(!b)return;const due=dueAmount(b);if(due<=0){alert('এই বিলটি সম্পূর্ণ পরিশোধিত।');return;}const raw=prompt('কত টাকা পরিশোধ হয়েছে?\nমোট বিল: '+money(billAmount(b))+'\nআগে পরিশোধ: '+money(paidAmount(b))+'\nএখন বাকি: '+money(due),String(due));if(raw===null)return;const amount=Number(raw);if(!Number.isFinite(amount)||amount<=0){alert('সঠিক পরিমাণ লিখুন।');return;}if(amount>due){alert('পরিশোধের পরিমাণ বাকি টাকার চেয়ে বেশি হতে পারবে না।');return;}b.amountPaid=paidAmount(b)+amount;b.paid=dueAmount(b)===0;b.paymentDate=today();save();renderBills();alert(b.paid?'বিলটি সম্পূর্ণ পরিশোধ হয়েছে।':'আংশিক পরিশোধ সংরক্ষিত হয়েছে।');}
function toggleBillPaid(i){const b=db.bills[i];if(!b)return;if(dueAmount(b)>0){addBillPayment(i);return;}if(!confirm('এই বিলের পরিশোধের তথ্য মুছে আবার সম্পূর্ণ বাকি করবেন?'))return;b.amountPaid=0;b.paid=false;b.paymentDate='';save();renderBills();}
function renderBills(){let m=$('billMonth').value||today().slice(0,7);$('billMonth').value=m;let a=db.bills.filter(x=>inMonth(x.date,m));let total=a.reduce((s,x)=>s+billAmount(x),0),paidTotal=a.reduce((s,x)=>s+paidAmount(x),0),unpaidTotal=a.reduce((s,x)=>s+dueAmount(x),0);let fullyPaid=a.filter(x=>dueAmount(x)===0&&billAmount(x)>0),unpaid=a.filter(x=>dueAmount(x)>0);$('billTotal').innerHTML=stat('মোট বিল',money(total))+stat('বিলের সংখ্যা',a.length);$('billPaymentSummary').innerHTML=stat('✓ পেয়েছি',money(paidTotal))+stat('✕ পাইনি',money(unpaidTotal))+stat('সম্পূর্ণ পরিশোধিত বিল',fullyPaid.length)+stat('বাকি / আংশিক বিল',unpaid.length);let f=$('billStatusFilter')?.value||'all';let shown=a.filter(x=>f==='all'||(f==='paid'?dueAmount(x)===0&&billAmount(x)>0:dueAmount(x)>0));$('billRows').innerHTML=shown.map(x=>{const i=db.bills.indexOf(x),total=billAmount(x),paid=paidAmount(x),due=dueAmount(x),fully=due===0&&total>0;return `<tr><td>${esc(x.date)}</td><td>${esc(x.place)}</td><td>${esc(personLabel(x.personCode))}</td><td>${esc(x.goingTransport||x.transport||'—')} · ${money(x.goingFare??x.travel)} / ${esc(x.returnTransport||'—')} · ${money(x.returnFare)}</td><td>${money(num(x.goingFare??x.travel)+num(x.returnFare))}</td><td>${money(x.food)}</td><td>${money(x.other)}</td><td><b>${money(total)}</b></td><td><b style="color:#15803d">${money(paid)}</b></td><td><b style="color:${due>0?'#dc2626':'#15803d'}">${money(due)}</b></td><td><span class="payment-mark ${fully?'paid':paid>0?'partial':'unpaid'}">${fully?'✓ পেয়েছি':'✕ পাইনি'}</span><br><small>${x.paymentDate?'সর্বশেষ: '+esc(x.paymentDate):''}</small></td><td><button class="${fully?'secondary':'green'}" onclick="${fully?'toggleBillPaid':'addBillPayment'}(${i})">${fully?'বাকি করুন':'＋ পেমেন্ট যোগ'}</button></td><td><button class="secondary" onclick="editBillRecord(${i})">✏️ এডিট</button> <button class="danger" onclick="del('bills',${i},renderBills)">মুছুন</button></td></tr>`}).join('')||'<tr><td colspan="13" style="text-align:center;padding:18px">এই ফিল্টারে কোনো বিল নেই।</td></tr>'}
$('personForm').addEventListener('submit',e=>{e.preventDefault();let x=formObj(e.target);if(db.people.some(p=>p.code.toLowerCase()===x.code.trim().toLowerCase()))return alert('এই ID কোড আগে থেকেই আছে।');db.people.push({name:x.name.trim(),code:x.code.trim(),records:[]});save();e.target.reset();refreshPersonLinks();renderFolders()});
function renderFolders(){$('personFolders').innerHTML=db.people.map((p,i)=>`<div class="folder" onclick="openPerson(${i})"><div class="ico">📁</div><b>${esc(p.name)}</b><small>${esc(p.code)}</small><p class="muted">${p.records.length}টি খরচের রেকর্ড</p></div>`).join('')}
function openPerson(i){activePerson=i;let p=db.people[i];$('personTitle').textContent=p.name;$('personCode').textContent='ID: '+p.code;$('personMonth').value=today().slice(0,7);showScreen('personScreen');renderPerson()}
$('personExpenseForm').addEventListener('submit',e=>{e.preventDefault();if(activePerson===null)return;db.people[activePerson].records.push(formObj(e.target));save();e.target.reset();renderPerson()});
function renderPerson(){
 if(activePerson===null)return;
 let p=db.people[activePerson],m=$('personMonth').value||today().slice(0,7);
 $('personMonth').value=m;
 let a=p.records.filter(x=>inMonth(x.date,m)).slice().sort((x,y)=>String(x.date).localeCompare(String(y.date)));
 let groups={};a.forEach(x=>(groups[x.date||'তারিখ নেই']??=[]).push(x));
 let out='';
 Object.keys(groups).sort().forEach(date=>{
   let rows=groups[date],dayTotal=0;
   out+=`<tr class="date-group"><td colspan="13">📅 ${esc(date)}</td></tr>`;
   rows.forEach(x=>{
     let travel=num(x.goingFare??x.travel)+num(x.returnFare),total=travel+num(x.food)+num(x.other);dayTotal+=total;
     let idx=p.records.indexOf(x),payer=x.payerCode?personLabel(x.payerCode):p.name;
     out+=`<tr><td>${esc(x.date||'—')}</td><td>${esc(x.time||'—')}</td><td>${esc(x.place||'—')}</td><td>${esc(x.goingTransport||x.transport||'—')} · ${money(x.goingFare??x.travel)} / ${esc(x.returnTransport||'—')} · ${money(x.returnFare)}</td><td>${money(travel)}</td><td>${esc(x.foodTime||'দিন')} · ${money(x.food)}</td><td>${money(x.other)}</td><td>${esc(x.reason)}</td><td>${esc(x.details)}</td><td><b>${money(total)}</b></td><td>${esc(payer)}</td><td><span class="payment-mark ${x.receivedStatus==='পেয়েছি'?'paid':'unpaid'}">${x.receivedStatus==='পেয়েছি'?'✓ পেয়েছি':'✕ পাইনি'}</span><br><button class="secondary" onclick="togglePersonReceived(${idx})">অবস্থা বদল</button></td><td><button class="danger" onclick="delPersonRecord(${idx})">মুছুন</button></td></tr>`;
   });
   out+=`<tr class="date-subtotal"><td colspan="9" style="text-align:right">তারিখের মোট</td><td colspan="4"><b>${money(dayTotal)}</b></td></tr>`;
 });
 $('personRows').innerHTML=out||'<tr><td colspan="13" style="text-align:center;padding:18px">এই মাসে কোনো খরচ নেই।</td></tr>';
 let travel=a.reduce((s,x)=>s+num(x.goingFare??x.travel)+num(x.returnFare),0),food=a.reduce((s,x)=>s+num(x.food),0),other=a.reduce((s,x)=>s+num(x.other),0);
 $('personTotals').innerHTML=stat('যাতায়াত মোট',money(travel))+stat('খাবার মোট',money(food))+stat('অন্যান্য মোট',money(other))+stat('সর্বমোট খরচ',money(travel+food+other))+stat('রেকর্ড সংখ্যা',a.length);
}
function togglePersonReceived(i){const r=db.people[activePerson]?.records?.[i];if(!r)return;r.receivedStatus=r.receivedStatus==='পেয়েছি'?'পাইনি':'পেয়েছি';save();renderPerson()}
function delPersonRecord(i){if(confirm('এই খরচের রেকর্ড মুছবেন?')){db.people[activePerson].records.splice(i,1);save();renderPerson()}}
function deletePerson(){if(activePerson===null)return;let p=db.people[activePerson];if(confirm(p.name+' এবং তার সব খরচের রেকর্ড মুছবেন? ')){db.people.splice(activePerson,1);activePerson=null;save();showScreen('expenseScreen')}}
function del(group,i,cb){if(confirm('রেকর্ডটি মুছবেন?')){db[group].splice(i,1);save();cb()}}
$('payForm').addEventListener('submit',e=>{e.preventDefault();db.pay.push(formObj(e.target));save();e.target.reset();renderPay()});
function togglePayReceived(i){const x=db.pay[i];if(!x)return;x.receivedStatus=x.receivedStatus==='পেয়েছি'?'পাইনি':'পেয়েছি';save();renderPay()}
function renderPay(){$('payRows').innerHTML=db.pay.slice().reverse().map(x=>`<div class="card"><b>${esc(x.type)}</b> · ${x.date}<h3>${money(x.amount)}</h3><p>${esc(x.place||'স্থান নেই')} · ${esc(personLabel(x.personCode))}</p><p>${esc(x.note)}</p><p><span class="payment-mark ${x.receivedStatus==='পেয়েছি'?'paid':'unpaid'}">${x.receivedStatus==='পেয়েছি'?'✓ পেয়েছি':'✕ পাইনি'}</span> <button class="secondary" onclick="togglePayReceived(${db.pay.indexOf(x)})">অবস্থা বদল</button></p></div>`).join('')}
$('customForm').addEventListener('submit',e=>{e.preventDefault();db.custom.push(formObj(e.target));save();e.target.reset();renderCustom()});
function renderCustom(){$('customRows').innerHTML=db.custom.slice().reverse().map((x,i)=>`<div class="card"><b>${esc(x.title)}</b> · ${x.date||'তারিখ নেই'}<p>${esc(x.place||'স্থান নেই')} · ${esc(personLabel(x.personCode))}</p><p>${esc(x.details)}</p><button class="danger" onclick="del('custom',${db.custom.length-1-i},renderCustom)">মুছুন</button></div>`).join('')}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

function pdfEscape(v){return String(v===undefined||v===null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pdfTable(title,rows){
  if(!Array.isArray(rows)||!rows.length)return `<section><h2>${pdfEscape(title)}</h2><p class="empty">কোনো রেকর্ড নেই</p></section>`;
  const keys=[...new Set(rows.flatMap(r=>Object.keys(r||{})))].filter(k=>k!=='id');
  return `<section><h2>${pdfEscape(title)}</h2><table><thead><tr>${keys.map(k=>`<th>${pdfEscape(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${pdfEscape(r?.[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></section>`;
}
function resetReportFilters(){['reportFrom','reportTo','reportPlace'].forEach(id=>{const e=$(id);if(e)e.value=''});const p=$('reportPerson');if(p)p.value='all'}
function reportFilterRows(rows,group){const from=$('reportFrom')?.value||'',to=$('reportTo')?.value||'',place=($('reportPlace')?.value||'').trim().toLocaleLowerCase(),personValue=$('reportPerson')?.value||'all';const selected=personValue==='all'?'':(db.people||[])[Number(personValue)]?.code||'__none__';return (rows||[]).filter(r=>{const d=String(r.date||'');if(from&&(!d||d<from))return false;if(to&&(!d||d>to))return false;if(place){const hay=[r.place,r.location,r.site,r.workPlace].filter(Boolean).join(' ').toLocaleLowerCase();if(!hay.includes(place))return false;}if(selected&&group!=='personExpense'&&r.personCode!==selected)return false;return true})}
function refreshReportPeople(){const sel=$('reportPerson');if(!sel)return;const old=sel.value;sel.innerHTML='<option value="all">সব ব্যক্তি</option>'+(db.people||[]).map((p,i)=>`<option value="${i}">${pdfEscape(p.name)} (${pdfEscape(p.code)})</option>`).join('');if([...sel.options].some(o=>o.value===old))sel.value=old}
function downloadFullPdf(){
  const from=$('reportFrom')?.value||'',to=$('reportTo')?.value||'',place=($('reportPlace')?.value||'').trim(),personValue=$('reportPerson')?.value||'all';
  if(from&&to&&from>to){alert('শুরুর তারিখ শেষ তারিখের পরে হতে পারে না।');return}
  const dateLabel=(from||'শুরু থেকে')+' — '+(to||'আজ পর্যন্ত');
  const sections=[];
  sections.push(`<section class="identity"><img class="report-banner" src="${db.profile?.photo||''}" alt="MPR SQUAD"><h2>${pdfEscape(db.profile?.name||'MP RAKIB sordar')}</h2><p>${pdfEscape(db.profile?.role||'MPR SQUAD')} · ${pdfEscape(db.profile?.tagline||'')}</p><p>রিপোর্ট তৈরির তারিখ: ${pdfEscape(today())}</p><p>সময়সীমা: ${pdfEscape(dateLabel)} | স্থান: ${pdfEscape(place||'সব স্থান')}</p></section>`);
  const duties=reportFilterRows(db.duties||[]).map(r=>({...r,person:personLabel(r.personCode)}));sections.push(pdfTable('ডিউটি ও ডে-অফ রেকর্ড',duties));
  const bills=reportFilterRows(db.bills||[]).map(b=>({...b,person:personLabel(b.personCode),totalBill:billAmount(b),paidAmount:paidAmount(b),dueAmount:dueAmount(b),paymentStatus:dueAmount(b)===0&&billAmount(b)>0?'সম্পূর্ণ পরিশোধিত':paidAmount(b)>0?'আংশিক পরিশোধ':'বাকি'}));
  sections.push(pdfTable('বিল ও পেমেন্টের হিসাব',bills));
  const selectedPeople=personValue==='all'?(db.people||[]):((db.people||[])[Number(personValue)]?[(db.people||[])[Number(personValue)]]:[]);
  sections.push(`<section><h2>ব্যক্তিভিত্তিক খরচ</h2>`);
  let grand={travel:0,food:0,other:0};
  if(selectedPeople.length){selectedPeople.forEach(p=>{const rows=reportFilterRows(p.records||[],'personExpense');const totals=rows.reduce((a,r)=>{a.travel+=num(r.travel);a.food+=num(r.food);a.other+=num(r.other);return a},{travel:0,food:0,other:0});grand.travel+=totals.travel;grand.food+=totals.food;grand.other+=totals.other;sections.push(`<h3>${pdfEscape(p.name)} (${pdfEscape(p.code)})</h3>`);sections.push(pdfTable('খরচের বিস্তারিত — তারিখ ও স্থানসহ',rows.map(r=>({...r,person:`${p.name} (${p.code})`,total:num(r.travel)+num(r.food)+num(r.other)}))));sections.push(`<p class="sum">যাতায়াত: ৳${totals.travel.toFixed(2)} | খাবার: ৳${totals.food.toFixed(2)} | অন্যান্য: ৳${totals.other.toFixed(2)} | ব্যক্তির মোট: ৳${(totals.travel+totals.food+totals.other).toFixed(2)}</p>`)});}else sections.push('<p class="empty">নির্বাচিত ব্যক্তির কোনো রেকর্ড নেই।</p>');
  sections.push(`<p class="sum">নির্বাচিত ব্যক্তিদের সর্বমোট খরচ: ৳${(grand.travel+grand.food+grand.other).toFixed(2)}</p></section>`);
  sections.push(pdfTable('বেতন / মোবাইল বিল / বোনাস',reportFilterRows(db.pay||[]).map(r=>({...r,person:personLabel(r.personCode)}))));
  sections.push(pdfTable('অন্যান্য তথ্য',reportFilterRows(db.custom||[]).map(r=>({...r,person:personLabel(r.personCode)}))));
  const reportHtml=`<!doctype html><html lang="bn"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MPR SQUAD Office Report</title><style>body{font-family:Arial,"Noto Sans Bengali",sans-serif;color:#172536;padding:22px;line-height:1.45}h2{font-size:18px;border-bottom:2px solid #245a85;padding-bottom:6px;margin-top:24px}h3{font-size:15px;margin:16px 0 6px}.identity{text-align:center;border:1px solid #ccd6e2;border-radius:10px;padding:16px}.report-banner{max-width:100%;max-height:120px;object-fit:contain}table{width:100%;border-collapse:collapse;font-size:11px;margin:8px 0 18px}th,td{border:1px solid #cbd5e1;padding:6px;text-align:left;overflow-wrap:anywhere}th{background:#edf2f8}.empty{color:#66758a}.sum{font-weight:bold;background:#f0f4f8;padding:8px}section{page-break-inside:auto}tr{page-break-inside:avoid}@page{size:A4 landscape;margin:12mm}@media print{body{padding:0}}
/* v3.4 home layout: brand first, horizontal time/date below */
header{justify-content:space-between}header .brand{flex:1}header button{background:#1766bd;border-radius:10px;padding:9px 13px;font-size:15px;font-weight:700}
.datetime-strip{display:flex;align-items:center;justify-content:center;flex-wrap:nowrap;gap:clamp(10px,4vw,30px);margin:10px 0 14px;padding:13px 16px;background:linear-gradient(115deg,#102b57,#174e78 55%,#146b73);border:1px solid #d6b45e;min-height:70px}
.datetime-strip .dt-part{display:flex;align-items:center;gap:9px;min-width:0}.datetime-strip .dt-icon{font-size:24px}.datetime-strip .dt-label{font-size:11px;opacity:.82;display:block}.datetime-strip strong{font-size:clamp(14px,3.5vw,19px);white-space:nowrap}.dt-divider{height:38px;width:1px;background:#ffffff66;flex:0 0 1px}
.home-main-grid .tile{min-height:112px;padding:17px 9px;font-size:15px}.home-main-grid .tile .ico{font-size:32px}
.drawer{overflow-y:auto}.drawer button{font-weight:650}
@media(max-width:380px){.datetime-strip{gap:9px;padding:10px 8px}.datetime-strip .dt-icon{font-size:19px}.datetime-strip strong{font-size:13px}.home-main-grid .tile{font-size:13px;min-height:100px}}

</style></head><body>${sections.join('')}<script>window.onload=()=>setTimeout(()=>window.print(),700)<\/script></body></html>`;if(window.AndroidBridge?.printHtml){window.AndroidBridge.printHtml(reportHtml);return;}const w=window.open('','_blank');if(!w){alert('পপ-আপ বন্ধ আছে। Chrome-এর pop-up অনুমতি দিয়ে আবার চেষ্টা করুন।');return}w.document.open();w.document.write(reportHtml);w.document.close();
}

function backup(){const content=JSON.stringify(db,null,2),filename='MPR_SQUAD_backup_'+today()+'.json';if(window.AndroidBridge?.saveTextFile){window.AndroidBridge.saveTextFile(filename,'application/json',content);return;}let blob=new Blob([content],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function backupCSV(){
 const rows=[['বিভাগ','তারিখ','ব্যক্তি','স্থান','বিবরণ','পরিমাণ','যাওয়ার মাধ্যম','যাওয়ার ভাড়া','আসার মাধ্যম','আসার ভাড়া','খাবারের সময়','পাওয়ার অবস্থা']];
 (db.duties||[]).forEach(x=>rows.push(['ডিউটি',x.date,personLabel(x.personCode),x.place,x.status,'','','','','','','']));
 (db.bills||[]).forEach(x=>rows.push(['বিল',x.date,personLabel(x.personCode),x.place,x.note,billAmount(x),x.goingTransport,x.goingFare,x.returnTransport,x.returnFare,'',dueAmount(x)>0?'পাইনি':'পেয়েছি']));
 (db.people||[]).forEach(p=>(p.records||[]).forEach(x=>rows.push(['ব্যক্তিগত খরচ',x.date,p.name,x.place,x.details,num(x.goingFare??x.travel)+num(x.returnFare)+num(x.food)+num(x.other),x.goingTransport,x.goingFare??x.travel,x.returnTransport,x.returnFare,x.foodTime,x.receivedStatus||'পাইনি'])));
 (db.pay||[]).forEach(x=>rows.push([x.type,x.date,personLabel(x.personCode),x.place,x.note,x.amount,'','','','','',x.receivedStatus||'পাইনি']));
 const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');
 if(window.AndroidBridge?.saveTextFile){window.AndroidBridge.saveTextFile('MPR_SQUAD_full_backup_'+today()+'.csv','text/csv;charset=utf-8',csv);return;}
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='MPR_SQUAD_full_backup_'+today()+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}

function restore(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let d=JSON.parse(r.result);if(!d.duties||!d.people||!d.bills)throw 0;if(confirm('বর্তমান ডেটা প্রতিস্থাপন করে ব্যাকআপ ফিরিয়ে আনবেন?')){db=d;save();alert('ব্যাকআপ রিস্টোর হয়েছে।');goHome()}}catch(_){alert('সঠিক ব্যাকআপ ফাইল নয়।')}};r.readAsText(f)}
function exportCSV(kind){if(kind!=='person'||activePerson===null)return;let p=db.people[activePerson],rows=[['Date','Time','Place','Going transport','Going fare','Return transport','Return fare','Food time','Food bill','Other','Payer','Received status','Reason','Details','Total'],...p.records.map(x=>[x.date,x.time,x.place,x.goingTransport||x.transport,x.goingFare??x.travel,x.returnTransport,x.returnFare,x.foodTime,x.food,x.other,x.payerCode?personLabel(x.payerCode):p.name,x.receivedStatus,x.reason,x.details,num(x.goingFare??x.travel)+num(x.returnFare)+num(x.food)+num(x.other)])];let csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');if(window.AndroidBridge?.saveTextFile){window.AndroidBridge.saveTextFile(p.code+'_expense.csv','text/csv;charset=utf-8',csv);return;}let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=p.code+'_expense.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
['dutyMonth','billMonth','personMonth'].forEach(id=>$(id).value=today().slice(0,7));
['dutyForm','billForm','personExpenseForm','payForm','customForm'].forEach(id=>{let el=$(id);let d=el.querySelector('[name=date]');if(d)d.value=today()});
renderHome();renderProfile();refreshPersonLinks();if($('summaryMonth'))$('summaryMonth').value=today().slice(0,7);window.addEventListener('popstate',()=>{const handled=appBack();if(handled)history.pushState({mpr:true},'','#app');});history.pushState({mpr:true},'','#app');

// One-page bill editor: all fields are editable together.
(function(){
 const css=`#billEditOverlay{position:fixed;inset:0;z-index:99999;background:rgba(8,15,45,.72);display:none;align-items:center;justify-content:center;padding:14px;overflow:auto}#billEditPanel{width:min(680px,100%);max-height:94vh;overflow:auto;background:linear-gradient(145deg,#fff,#eef4ff);border:2px solid #7c3aed;border-radius:22px;padding:18px;box-shadow:0 18px 60px #0006;color:#172554}#billEditPanel h2{margin:0 0 6px;background:linear-gradient(90deg,#4f46e5,#9333ea,#0891b2);color:white;padding:14px;border-radius:14px}#billEditForm{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:14px}#billEditForm label{display:block;font-weight:700;margin-bottom:5px;color:#312e81}#billEditForm input,#billEditForm select,#billEditForm textarea{width:100%;box-sizing:border-box;border:1px solid #c7d2fe;border-radius:10px;padding:11px;background:white;color:#111827;font:inherit}#billEditForm .wide{grid-column:1/-1}#billEditForm .actions{display:flex;gap:9px;flex-wrap:wrap}@media(max-width:480px){#billEditForm{grid-template-columns:1fr}#billEditForm .wide{grid-column:auto}}`;
 const st=document.createElement('style');st.textContent=css;document.head.appendChild(st);
 const wrap=document.createElement('div');wrap.id='billEditOverlay';wrap.innerHTML=`<div id="billEditPanel" role="dialog" aria-modal="true"><h2>✏️ বিল সম্পাদনা</h2><p>সব তথ্য এক পেজে পরিবর্তন করে শেষে একবার সংরক্ষণ করুন।</p><form id="billEditForm"><div><label>তারিখ</label><input name="date" type="date" required></div><div><label>কাজের স্থান</label><input name="place" required></div><div><label>সংশ্লিষ্ট ব্যক্তি</label><select name="personCode" class="person-link"><option value="">ব্যক্তি নির্বাচন (ঐচ্ছিক)</option></select></div><div><label>যাওয়ার মাধ্যম</label><select name="goingTransport"><option value="">নির্বাচন</option><option>রিকশা</option><option>🚌 বাস</option><option>🛺 অটো</option><option>🚕 CNG</option><option>🏍️ মোটরসাইকেল</option><option>🚘 প্রাইভেট কার</option><option>অন্যান্য</option></select></div><div><label>যাওয়ার ভাড়া (৳)</label><input name="goingFare" type="number" min="0" step="0.01"></div><div><label>আসার মাধ্যম</label><select name="returnTransport"><option value="">নির্বাচন</option><option>রিকশা</option><option>🚌 বাস</option><option>🛺 অটো</option><option>🚕 CNG</option><option>🏍️ মোটরসাইকেল</option><option>🚘 প্রাইভেট কার</option><option>অন্যান্য</option></select></div><div><label>আসার ভাড়া (৳)</label><input name="returnFare" type="number" min="0" step="0.01"></div><div><label>খাবার বিল (৳)</label><input name="food" type="number" min="0" step="0.01"></div><div><label>অন্যান্য খরচ (৳)</label><input name="other" type="number" min="0" step="0.01"></div><div><label>এ পর্যন্ত পরিশোধ (৳)</label><input name="amountPaid" type="number" min="0" step="0.01" value="0"></div><div><label>বিলের অবস্থা</label><select name="paid"><option value="false">বাকি / আংশিক</option><option value="true">সম্পূর্ণ পরিশোধিত</option></select></div><div class="wide"><label>মন্তব্য / বিস্তারিত</label><textarea name="note" rows="3"></textarea></div><div class="wide"><b>মোট বিল: ৳ <span id="be_total">0</span></b></div><div class="wide actions"><button class="green" type="submit">✓ সব পরিবর্তন সংরক্ষণ</button><button class="secondary" type="button" onclick="closeBillEditor()">বাতিল</button></div></form></div>`;
 document.body.appendChild(wrap);
})();
let billEditIndex=null;
function editBillRecord(i){const b=db.bills[i];if(!b)return;billEditIndex=i;const f=document.getElementById('billEditForm');['date','place','goingTransport','goingFare','returnTransport','returnFare','food','other','note'].forEach(k=>{f.elements[k].value=b[k]??(k.toLowerCase().includes('fare')||['food','other'].includes(k)?0:'')});if(f.elements.personCode)f.elements.personCode.value=b.personCode||'';f.elements.amountPaid.value=paidAmount(b);f.elements.paid.value=dueAmount(b)===0&&billAmount(b)>0?'true':'false';updateBillEditTotal();document.getElementById('billEditOverlay').style.display='flex';}
function closeBillEditor(){document.getElementById('billEditOverlay').style.display='none';billEditIndex=null;}
function updateBillEditTotal(){const f=document.getElementById('billEditForm');const total=['goingFare','returnFare','food','other'].reduce((a,k)=>a+(Number(f.elements[k].value)||0),0);document.getElementById('be_total').textContent=total.toLocaleString('en-BD',{maximumFractionDigits:2})+' · বাকি '+Math.max(0,total-(Number(f.elements.amountPaid.value)||0)).toLocaleString('en-BD',{maximumFractionDigits:2});}
document.getElementById('billEditForm').addEventListener('input',updateBillEditTotal);
document.getElementById('billEditForm').elements.paid.addEventListener('change',e=>{const f=document.getElementById('billEditForm');if(e.target.value==='true'){f.elements.amountPaid.value=['goingFare','returnFare','food','other'].reduce((a,k)=>a+(Number(f.elements[k].value)||0),0);}else if(Number(f.elements.amountPaid.value)>0){f.elements.amountPaid.value=0;}updateBillEditTotal();});
document.getElementById('billEditForm').addEventListener('submit',e=>{e.preventDefault();if(billEditIndex===null)return;const f=e.currentTarget,old=db.bills[billEditIndex];if(!old)return;const total=['goingFare','returnFare','food','other'].reduce((a,k)=>a+(Number(f.elements[k].value)||0),0);const amountPaid=Math.min(total,Math.max(0,Number(f.elements.amountPaid.value)||0));db.bills[billEditIndex]={...old,date:f.elements.date.value,place:f.elements.place.value.trim(),personCode:f.elements.personCode?.value||'',goingTransport:f.elements.goingTransport.value,goingFare:Number(f.elements.goingFare.value)||0,returnTransport:f.elements.returnTransport.value,returnFare:Number(f.elements.returnFare.value)||0,food:Number(f.elements.food.value)||0,other:Number(f.elements.other.value)||0,amountPaid,paid:amountPaid>=total&&total>0,note:f.elements.note.value.trim()};save();closeBillEditor();renderBills();alert('বিলের সব পরিবর্তন সংরক্ষণ হয়েছে।');});
document.getElementById('billEditOverlay').addEventListener('click',e=>{if(e.target.id==='billEditOverlay')closeBillEditor();});


